class Shape {
  accept(visitor) { return visitor.visit(this); }
}
class Circle extends Shape {
  constructor(r) { super(); this.r = r; }
}
class AreaVisitor {
  visit(circle) { return Math.PI * circle.r * circle.r; }
}
console.log(new Circle(5).accept(new AreaVisitor()));
